using System;using System.IO;using System.Text;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using Frociart;
internal static class CodeTemplateUiTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static void Pump(int ms=60){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(3);}}
 static void Until(Func<bool> ready,string why){var until=DateTime.UtcNow.AddSeconds(15);while(!ready()&&DateTime.UtcNow<until)Pump();Check(ready(),why);}
 static void Capture(Form form,string path){Pump(220);using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
 static FlowTemplateDraft Draft(string name,string body){return new FlowTemplateDraft(name,"python","py",FlowSourceTarget.Python.Instructions,body);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=args[0],folder=Path.Combine(root,"ui-store",FlowTemplateStore.NewId());var store=new FlowTemplateStore(folder);var doc=FlowPseudocode.Decode("x=2\nSTAMPA x+1");string before=Convert.ToBase64String(DiagramIO.EncodeDocument(doc)),id=FlowTemplateStore.NewId();UiMotion.SetEnabled(true);
  using(var editor=new CodeTemplateEditor(store,id,Draft("Nuovo","{{ source }}"),doc)){editor.Show();Pump();editor.NameField.Text="";editor.BodyField.Text="{% if true %}\n🐢";editor.Close();Until(()=>!editor.Visible,"Close waits for actual unfinished draft persistence");var saved=FlowTemplateDraft.Decode(store.Load(id).Draft);Check(saved.Name==""&&saved.Body=="{% if true %}\n🐢"&&store.Load(id).Definition==null,"Incomplete form and invalid syntax survive close");}
  using(var editor=new CodeTemplateEditor(store,id,null,doc)){editor.Show();Pump();Check(editor.NameField.Text==""&&editor.BodyField.Text.Contains("🐢"),"Native editor reopens exact unfinished form");editor.NameField.Text="Ripreso";editor.BodyField.Text="# Il mio modello\n{{ source }}";editor.SaveButton.PerformClick();editor.Close();Check(editor.Visible,"X cannot close the editor during a pending save");Until(()=>!editor.Visible,"Save waits for real main-file commit");Check(editor.Saved!=null&&store.Load(id).Definition.Name=="Ripreso"&&store.Load(id).Draft==null,"Saved definition and exact matching draft cleanup are real");}
  using(var editor=new CodeTemplateEditor(store,id,null,doc)){editor.Show();Pump();var old=store.Load(id);store.Save(id,Draft("Cambio esterno","{{ source }}").Definition().Text,old.Fingerprint);editor.NameField.Text="Il mio tentativo";editor.BodyField.Text="# Il mio testo\n{{ source }}";editor.SaveButton.PerformClick();Until(()=>editor.LastError!=null,"Concurrent save is rejected visibly");Check(editor.Visible&&editor.BodyField.Text.Contains("Il mio testo")&&store.Load(id).Definition.Name=="Cambio esterno","Conflict retains form and newer saved model");editor.Close();Until(()=>!editor.Visible,"Conflict can close while preserving recoverable draft");Check(FlowTemplateDraft.Decode(store.Load(id).Draft).Name=="Il mio tentativo","Failed main save still retains newest form draft");}
  var entry=store.Load(id);store.ClearDraft(id,entry.Draft);entry=store.Save(id,Draft("Ripreso","# Il mio modello\n{{ source }}").Definition().Text,entry.Fingerprint);var target=FlowSourceTarget.FromTemplate(id,entry.Definition);
  using(var source=new SourceCodeDialog(doc,(function,node)=>{},target)){source.Show();Pump();Check(source.Source!=null&&source.Source.Language=="python"&&source.Text.Contains("Ripreso"),"Personal target opens actual source viewer");Check(source.Editor.AccessibleName.Contains("Ripreso")&&source.Editor.ReadOnly,"Personal source has accessible template name and native selectable text");string copied=null;source.ClipboardWrite=text=>copied=text;source.Copy.PerformClick();Check(copied==source.Source.Text&&copied.Contains("Il mio modello"),"Native copy exports complete personalized source to owned sink");SourceCodeDialog.WriteSource(Path.Combine(root,"ui-personal.py"),source.Source.Text);Check(File.ReadAllText(Path.Combine(root,"ui-personal.py"))==copied,"Actual personalized source save");var block=doc.Nodes.First(n=>n.Kind==NodeKind.Process);var line=source.Source.ForBlock(null,block.Id).First();source.Editor.Select(source.Editor.GetFirstCharIndexFromLine(line.Number-1),0);Check(source.SelectedOrigin().NodeId==block.Id,"Personal header offsets still map to original flowchart block");source.Close();}
  foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);var longTarget=FlowSourceTarget.FromTemplate(id,FlowCodeTemplate.Create(new string('M',80),"python","py",new string('I',1000),"{{ source }}"));using(var source=new SourceCodeDialog(doc,null,longTarget)){source.Size=new Size(640,480);source.Show();Pump();Check(source.Editor.Height>=100&&source.Copy.Visible&&source.Save.Visible,"Long custom instructions leave editor usable in minimum window");Capture(source,Path.Combine(root,"template-source-"+(dark?"dark":"light")+".png"));source.Close();}}
  var empty=FlowSourceTarget.FromTemplate(id,FlowCodeTemplate.Create("Vuoto","custom","txt","",""));using(var source=new SourceCodeDialog(doc,null,empty)){source.Show();Pump();Check(source.Source!=null&&source.Source.Text==""&&!source.Copy.Enabled&&!source.Save.Enabled&&!source.Support.Visible,"Empty template output is explicit and cannot copy empty clipboard text");source.Close();}
  using(var library=new CodeTemplateLibrary(store,doc)){library.Show();Until(()=>library.Results.Enabled&&library.Results.Items.Count==1,"Library loads asynchronously after native handle creation");library.Search.Text="inesistente";Check(library.Results.Items.Count==0&&!library.UseButton.Enabled,"Search and empty selection disable unavailable actions");library.Search.Text="Ripreso";Check(library.Results.Items.Count==1&&library.UseButton.Enabled,"Search recovers saved model");library.ExportPathPicker=name=>Path.Combine(root,"ui-model.frotemplate");library.ExportButton.PerformClick();Until(()=>File.Exists(Path.Combine(root,"ui-model.frotemplate"))&&library.ExportButton.Enabled,"Export action writes actual template file");Check(FlowCodeTemplate.Parse(FlowTemplateStore.ReadImport(Path.Combine(root,"ui-model.frotemplate"))).Name=="Ripreso","Exported template really reimports");
   string importedPath=Path.Combine(root,"ui-model.frotemplate");Exception nestedError=null;var timer=new System.Windows.Forms.Timer{Interval=25};timer.Tick+=delegate{var editor=Application.OpenForms.OfType<CodeTemplateEditor>().FirstOrDefault(e=>e.Visible);if(editor==null)return;timer.Stop();try{Check(editor.NameField.Text=="Ripreso (2)","Duplicate import gets explicit distinct name and fresh model ID");editor.SaveButton.PerformClick();}catch(Exception error){nestedError=error;editor.Dispose();}};timer.Start();library.ImportPathPicker=()=>importedPath;library.ImportButton.PerformClick();Until(()=>store.Entries().Count==2&&library.Results.Enabled,"Import review/save updates private library");timer.Stop();timer.Dispose();if(nestedError!=null)throw nestedError;
   library.ImportPathPicker=()=>null;library.ImportButton.PerformClick();Check(store.Entries().Count==2,"Cancelled import changes no model");string bad=Path.Combine(root,"bad-template.frotemplate");File.WriteAllBytes(bad,new byte[]{255,255});library.ImportFromPath(bad);Until(()=>library.LastError!=null,"Bad UTF8 import reports real failure");Check(store.Entries().Count==2,"Bad import preserves earlier library entries");
   library.Search.Text="Ripreso (2)";Until(()=>library.Results.Items.Count==1&&library.ArchiveButton.Enabled,"Imported model can be selected");library.ArchiveButton.PerformClick();Until(()=>store.Entries(true).Count==1&&library.Results.Enabled,"Archive action retains model in recoverable trash");library.Search.Text="";library.Trash.Checked=true;Until(()=>library.Results.Enabled&&library.Results.Items.Count==1,"Trash lists archived model");Check(library.ArchiveButton.Text=="Ripristina"&&!library.UseButton.Enabled,"Trash actions distinguish restore and use");library.ArchiveButton.PerformClick();Until(()=>store.Entries(true).Count==0&&library.Results.Enabled,"Restore action preserves model");library.Trash.Checked=false;Until(()=>library.Results.Enabled&&library.Results.Items.Count==2,"Active list recovers restored models");Capture(library,Path.Combine(root,"template-library.png"));library.UseButton.PerformClick();Check(library.SelectedTarget!=null&&!library.Visible,"Use chooses actual immutable template descriptor");}
  using(var main=new MainForm(null,true)){main.Show();main.EnterEditor();main.SetWorkspaceLayout(1,false);main.SetDocument(doc,null,false);typeof(MainForm).GetField("templateStore",F).SetValue(main,store);var preview=(PseudocodePreview)typeof(MainForm).GetField("livePseudocode",F).GetValue(main);preview.SetTarget(target);Pump();Check(preview.SourceMode&&preview.SourceLanguage==target.Id&&preview.PythonCode.Source.Text.Contains("Il mio modello"),"Actual live sidebar uses personal template");var current=store.Load(id);store.Save(id,Draft("Aggiornato","# AGGIORNATO\n{{ source }}").Definition().Text,current.Fingerprint);
   var timer=new System.Windows.Forms.Timer{Interval=25};timer.Tick+=delegate{var library=Application.OpenForms.OfType<CodeTemplateLibrary>().FirstOrDefault(f=>f.Visible&&f.CloseButton.Enabled);if(library!=null){timer.Stop();library.CloseButton.PerformClick();}};timer.Start();main.ShowCodeTemplates(true);Check(preview.SelectedTarget.Name=="Aggiornato"&&preview.PythonCode.Source.Text.Contains("AGGIORNATO"),"Closing actual manager refreshes the selected live model revision");current=store.Load(id);store.Archive(id,current.Fingerprint);timer.Start();main.ShowCodeTemplates(true);timer.Stop();timer.Dispose();Check(!preview.SourceMode&&preview.SourceLanguage=="pseudocode","Archived live model recovers to pseudocode");main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();}
  Check(Convert.ToBase64String(DiagramIO.EncodeDocument(doc))==before,"Template editing, library and source actions never mutate original diagram");Console.WriteLine("TEMPLATE_UI_PC PASS checks="+checks);return 0;
 }catch(Exception error){Console.WriteLine(error);return 1;}}
}
